// Some portions generated by Codex
package org.eclipse.rdf4j.query.impl;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.base.AbstractTripleTerm;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.junit.jupiter.api.Test;

class RemoteBNodeProvenanceTraversalTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:provenance:p");
	private static final Resource SUBJECT = VF.createIRI("urn:provenance:s");

	@Test
	void unchangedDeepTripleIsReturnedWithoutWalkingForeignValues() {
		AtomicInteger reads = new AtomicInteger();
		ColdLeaf coldLeaf = new ColdLeaf();
		Value original = chain(10_000, coldLeaf, reads);

		assertSame(original, RemoteBNode.preserveProvenance(original, original));
		assertThat(reads).hasValue(0);
		assertThat(coldLeaf.accessCount).hasValue(0);
	}

	@Test
	void copiedDeepTriplePreservesNestedAliasWithoutRecursiveTraversal() {
		int depth = 10_000;
		Object identityScope = new Object();
		BNode originalAlias = (BNode) responseScope(identityScope).map(VF.createBNode("nested-origin"));
		AtomicInteger originalReads = new AtomicInteger();
		AtomicInteger capturedReads = new AtomicInteger();
		ColdLeaf coldLeaf = new ColdLeaf();
		Value originalTerminal = new CountingTriple((Resource) originalAlias, PREDICATE, coldLeaf, originalReads);
		Value capturedTerminal = new CountingTriple(VF.createBNode(originalAlias.getID()), PREDICATE, coldLeaf,
				capturedReads);
		Value original = chain(depth - 1, originalTerminal, originalReads);
		Value captured = chain(depth - 1, capturedTerminal, capturedReads);

		Value preserved = RemoteBNode.preserveProvenance(original, captured);

		assertThat(preserved).isNotSameAs(captured);
		assertThat(originalReads.get()).isLessThanOrEqualTo(6 * depth);
		assertThat(capturedReads.get()).isLessThanOrEqualTo(6 * depth);
		Value current = preserved;
		for (int level = 0; level < depth - 1; level++) {
			current = ((TripleTerm) current).getObject();
		}
		BNode nestedAlias = (BNode) ((TripleTerm) current).getSubject();
		assertThat(nestedAlias).isInstanceOf(RemoteBNode.class);
		assertThat(RemoteBNode.sameTrustedIdentity((RemoteBNode) originalAlias, (RemoteBNode) nestedAlias)).isTrue();
		assertThat(coldLeaf.accessCount).hasValue(0);
	}

	@Test
	void copiedDeepTripleWithoutRemoteAliasesReusesCapturedTreeAndColdLeaf() {
		int depth = 50_000;
		AtomicInteger originalReads = new AtomicInteger();
		AtomicInteger capturedReads = new AtomicInteger();
		ColdLeaf coldLeaf = new ColdLeaf();
		Value original = chain(depth, coldLeaf, originalReads);
		Value captured = chain(depth, coldLeaf, capturedReads);

		assertSame(captured, RemoteBNode.preserveProvenance(original, captured));
		assertThat(originalReads).hasValue(2 * depth);
		assertThat(capturedReads).hasValue(2 * depth);
		assertThat(coldLeaf.accessCount).hasValue(0);
	}

	@Test
	void nestedCopiesRetainSharedRemoteIdentityAndLostOrMismatchedCopiesAreRejected() {
		Object identityScope = new Object();
		BNode originalAlias = (BNode) responseScope(identityScope).map(VF.createBNode("shared-origin"));
		Value original = VF.createTripleTerm((Resource) originalAlias, PREDICATE,
				VF.createTripleTerm(SUBJECT, PREDICATE, originalAlias));
		Value captured = VF.createTripleTerm(VF.createBNode(originalAlias.getID()), PREDICATE,
				VF.createTripleTerm(SUBJECT, PREDICATE, VF.createBNode(originalAlias.getID())));

		TripleTerm preserved = (TripleTerm) RemoteBNode.preserveProvenance(original, captured);
		BNode subject = (BNode) preserved.getSubject();
		BNode object = (BNode) ((TripleTerm) preserved.getObject()).getObject();
		assertThat(subject).isInstanceOf(RemoteBNode.class);
		assertThat(object).isInstanceOf(RemoteBNode.class);
		assertThat(RemoteBNode.sameTrustedIdentity((RemoteBNode) subject, (RemoteBNode) object)).isTrue();
		assertThat(RemoteBNode.toRemoteValue(subject, identityScope, true, true))
				.isEqualTo(VF.createBNode("shared-origin"));

		assertThatThrownBy(() -> RemoteBNode.preserveProvenance(originalAlias,
				VF.createBNode("different-alias")))
						.isInstanceOf(QueryEvaluationException.class)
						.hasMessageContaining("value copy changed its alias");
		assertThatThrownBy(() -> RemoteBNode.preserveProvenance(original, VF.createIRI("urn:lost-copy")))
				.isInstanceOf(QueryEvaluationException.class)
				.hasMessageContaining("value copy lost nested provenance");
	}

	@Test
	void containsRemoteIdentityTraversesDeepForeignValuesWithoutRecursion() {
		int depth = 50_000;
		AtomicInteger reads = new AtomicInteger();
		ColdLeaf coldLeaf = new ColdLeaf();
		Value noRemoteIdentity = chain(depth, coldLeaf, reads);
		assertThat(RemoteBNode.containsRemoteIdentity(noRemoteIdentity)).isFalse();
		assertThat(reads).hasValue(2 * depth);
		assertThat(coldLeaf.accessCount).hasValue(0);

		Object identityScope = new Object();
		BNode alias = (BNode) responseScope(identityScope).map(VF.createBNode("deep-origin"));
		Value withRemoteIdentity = chain(depth, alias, new AtomicInteger());
		assertThat(RemoteBNode.containsRemoteIdentity(withRemoteIdentity)).isTrue();
	}

	private static RemoteBNode.ResponseScope responseScope(Object identityScope) {
		return RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF, identityScope, true);
	}

	private static Value chain(int depth, Value leaf, AtomicInteger reads) {
		Value value = leaf;
		for (int level = 0; level < depth; level++) {
			value = new CountingTriple(SUBJECT, PREDICATE, value, reads);
		}
		return value;
	}

	private static final class CountingTriple extends AbstractTripleTerm {
		private static final long serialVersionUID = 1L;
		private final Resource subject;
		private final IRI predicate;
		private final Value object;
		private final AtomicInteger reads;

		private CountingTriple(Resource subject, IRI predicate, Value object, AtomicInteger reads) {
			this.subject = subject;
			this.predicate = predicate;
			this.object = object;
			this.reads = reads;
		}

		@Override
		public Resource getSubject() {
			reads.incrementAndGet();
			return subject;
		}

		@Override
		public IRI getPredicate() {
			reads.incrementAndGet();
			return predicate;
		}

		@Override
		public Value getObject() {
			reads.incrementAndGet();
			return object;
		}
	}

	private static final class ColdLeaf implements Value {
		private static final long serialVersionUID = 1L;
		private final AtomicInteger accessCount = new AtomicInteger();

		@Override
		public String stringValue() {
			accessCount.incrementAndGet();
			throw new AssertionError("cold foreign leaf must not be dereferenced");
		}
	}
}
